}>()
const router = useRouter()
const authStore = useAuthStore()

const navItems = [{ path: '/home', label: 'Home', icon: 'home' }, { path: '/search', label: 'Search', icon: 'search' }, { path: '/library', label: 'Your Library', icon: 'library' }] as const

const windowWidth = computed(() => (window as any).innerWidth)

function renderIcon(name: string) { switch (name) { case 'home': return h('svg', { width: 24, height: 24, viewBox: '0 0 24 24', fill: 'currentColor' }, [h('path', { d: 'M10 20v-6h4v6h5v-8h3L12 3 2 12h3v8z' })]); case 'search': return h('svg', { width: 24, height: 24, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': 2 }, [h('circle', { cx: 11, cy: 11, r: 8 }), h('line', { x1: 21, y1: 21, x2: 16.65, y2: 16.65 })]); case 'library': return h('svg', { width: 24, height: 24, viewBox: '0 0 24 24', fill: 'none', stroke: 'currentColor', 'stroke-width': 2 }, [h('rect', { x: 2, y: 3, width: 20, height: 14, rx: 2, ry: 2 }), h('path', { d: 'M8 21h8' }), h('path', { d: 'M12 17v4' })]) } }
function nav(p: string) { Haptics.impact({ style: ImpactStyle.Light }); router.push(p); if (windowWidth.value < 768) { emit('update:modelValue', false); emit('close') } }
function logout() { authStore.logout(); router.push('/login'); emit('update:modelValue', false); emit('close') }
</script>

